// ═══════════════════════════════════════
// PHASE 1: RETRIEVAL PLANNING
// ═══════════════════════════════════════
const body = $input.first().json.body || {};

const task = body.task || body.query || '';
const brand = body.brand || '';
const product = body.product || '';
const audience = body.audience || '';
const platform = body.platform || 'instagram'; // instagram, tiktok, facebook, twitter, linkedin
const contentType = body.contentType || 'auto'; // image, video, carousel, story, reel, auto
const tone = body.tone || 'professional';
const publish = body.publish !== false; // true = publish immediately, false = draft only
const schedule = body.schedule || null; // ISO datetime for scheduled publishing

const knowledgeRequired = [];
if (task.toLowerCase().includes('campaign') || task.toLowerCase().includes('حملة')) {
  knowledgeRequired.push('Campaign History', 'Performance Analytics', 'Audience Knowledge');
}
if (task.toLowerCase().includes('content') || task.toLowerCase().includes('محتوى')) {
  knowledgeRequired.push('Historical Content', 'Trend Intelligence', 'Brand Knowledge');
}
if (task.toLowerCase().includes('competitor') || task.toLowerCase().includes('منافس')) {
  knowledgeRequired.push('Competitor Intelligence', 'Market Intelligence');
}
if (knowledgeRequired.length === 0) {
  knowledgeRequired.push('Brand Knowledge', 'Product Knowledge', 'Audience Knowledge', 'Trend Intelligence');
}

const plan = {
  task,
  brand,
  product,
  audience,
  platform,
  contentType,
  tone,
  publish,
  schedule,
  knowledge_required: knowledgeRequired,
  sources_required: ['memory', 'performance', 'external'],
  time_sensitivity: body.timeSensitivity || 'medium',
  freshness_requirement: body.timeSensitivity === 'high' ? 'last_7_days' : 'last_30_days',
  confidence_requirement: body.confidenceRequirement || 0.75,
  session_id: body.sessionId || 'sess-' + Date.now(),
  timestamp: new Date().toISOString()
};

return [{ json: plan }];

// ═══════════════════════════════════════
// PHASE 3: FILTER + RERANK + GRADE
// ═══════════════════════════════════════
const plan = $input.first().json;

const memoryItems = $items('2a. Retrieve Memory').map(item => ({
  source: 'memory', type: item.json.knowledge_type || 'unknown',
  content: item.json.insight || '', confidence: item.json.confidence || 0.5,
  authority: 0.9, freshness: item.json.created_at ? (new Date() - new Date(item.json.created_at)) / (1000*60*60*24) : 30,
  business_fit: 0.8, performance_relevance: item.json.source_campaigns ? 0.85 : 0.5
}));

const perfItems = $items('2b. Retrieve Performance').map(item => ({
  source: 'performance', type: 'performance_analytics',
  content: `Campaign: ${item.json.campaign_name} | Platform: ${item.json.platform} | CTR: ${item.json.ctr}% | ROAS: ${item.json.roas} | Creative: ${item.json.creative_angle}`,
  confidence: item.json.roas > 3 ? 0.9 : item.json.roas > 1.5 ? 0.75 : 0.5,
  authority: 0.95, freshness: item.json.created_at ? (new Date() - new Date(item.json.created_at)) / (1000*60*60*24) : 30,
  business_fit: 0.9, performance_relevance: 1.0
}));

const brandItems = $items('2c. Retrieve Brand Rules').map(item => ({
  source: 'brand', type: 'brand_knowledge',
  content: `${item.json.knowledge_type}: ${item.json.content}`,
  confidence: item.json.priority === 1 ? 0.95 : 0.7,
  authority: 1.0, freshness: 0, business_fit: 1.0, performance_relevance: 0.3
}));

const all = [...memoryItems, ...perfItems, ...brandItems];

const scored = all.map(item => {
  const relevance = item.confidence;
  const authority = item.authority;
  const freshness = Math.max(0, 1 - (item.freshness / 30));
  const businessFit = item.business_fit;
  const perfRel = item.performance_relevance;
  const composite = relevance*0.30 + authority*0.25 + freshness*0.15 + businessFit*0.15 + perfRel*0.15;
  return { ...item, composite_score: parseFloat(composite.toFixed(3)) };
});

const threshold = plan.confidence_requirement || 0.5;
const reranked = scored.filter(i => i.composite_score >= threshold).sort((a,b) => b.composite_score - a.composite_score).slice(0, 10);

const evidenceSufficient = reranked.length >= 3 && reranked[0].composite_score >= 0.7;
const missingDomains = plan.knowledge_required.filter(k => !reranked.some(r => r.type.toLowerCase().includes(k.toLowerCase())));

return [{ json: { ...plan, retrieved_items: reranked, evidence_sufficient: evidenceSufficient, confidence: reranked.length > 0 ? reranked[0].composite_score : 0, missing_information: missingDomains } }];

// بناء سياق للتوليف
const data = $input.first().json;
const items = data.retrieved_items || [];

const context = items.map((item, i) => `[${i+1}] ${item.source.toUpperCase()} | ${item.type} | Score: ${item.composite_score}\n${item.content}`).join('\n\n');

const systemPrompt = `You are AGENTIC-RAG-Ω, a marketing intelligence engine.
Analyze evidence and create a STRATEGIC CONTENT BRIEF.

OUTPUT FORMAT (JSON):
{
  "content_strategy": "brief strategy summary",
  "visual_concept": "detailed visual direction for image/video",
  "caption": "engaging social media caption in the user's language",
  "hashtags": ["tag1", "tag2", "tag3", "tag4", "tag5"],
  "cta": "call to action",
  "image_prompt": "detailed DALL-E prompt for image generation",
  "video_prompt": "detailed video generation prompt (if video requested)",
  "tone_check": "how this aligns with brand voice",
  "confidence": 0.0
}`;

const userPrompt = `TASK: ${data.task}
BRAND: ${data.brand || 'N/A'}
PRODUCT: ${data.product || 'N/A'}
AUDIENCE: ${data.audience || 'N/A'}
PLATFORM: ${data.platform}
CONTENT TYPE: ${data.contentType}
TONE: ${data.tone}

EVIDENCE:
${context}

Generate the content brief.`;

return [{ json: { ...data, synthesis_input: { systemPrompt, userPrompt } } }];

// parse AI response
const ai = $input.first().json;
let brief = {};
try {
  brief = typeof ai.output === 'string' ? JSON.parse(ai.output) : ai.output || ai;
} catch(e) {
  brief = { content_strategy: ai.output || ai.text || '', visual_concept: '', caption: '', hashtags: [], cta: '', image_prompt: '', video_prompt: '' };
}
return [{ json: { ...$items('4. Prepare Synthesis')[0].json, content_brief: brief } }];

// Note: Video generation requires external API (Runway, Pika, etc.)
// This node prepares the prompt for manual or API-based generation
const data = $input.first().json;
const videoPrompt = data.content_brief.video_prompt || data.content_brief.image_prompt || '';
return [{ json: { ...data, video_generation_prompt: videoPrompt, video_status: 'pending_external_api' } }];

// Determine publish route based on platform
const data = $input.first().json;
const platform = data.platform?.toLowerCase() || 'instagram';
const shouldPublish = data.publish !== false;

const routes = {
  instagram: { node: 'Publish Instagram', endpoint: 'instagram' },
  facebook: { node: 'Publish Facebook', endpoint: 'facebook' },
  twitter: { node: 'Publish X/Twitter', endpoint: 'twitter' },
  linkedin: { node: 'Publish LinkedIn', endpoint: 'linkedin' },
  tiktok: { node: 'Publish TikTok', endpoint: 'tiktok' }
};

const route = routes[platform] || routes.instagram;

return [{ json: { ...data, publish_route: route, should_publish: shouldPublish } }];

// TikTok requires Creator Portal API — placeholder for future integration
const data = $input.first().json;
return [{ json: { ...data, tiktok_publish_status: 'requires_manual_upload', video_prompt: data.video_generation_prompt } }];

// Structure final response
const data = $input.first().json;
const brief = data.content_brief || {};

return [{ json: {
  success: true,
  session_id: data.session_id,
  retrieval_plan: {
    task: data.task,
    knowledge_required: data.knowledge_required,
    confidence_requirement: data.confidence_requirement
  },
  content_brief: {
    strategy: brief.content_strategy,
    visual_concept: brief.visual_concept,
    caption: brief.caption,
    hashtags: brief.hashtags,
    cta: brief.cta,
    tone_check: brief.tone_check
  },
  generated_assets: {
    image_url: data.generated_image_url || data.image_url || null,
    video_prompt: data.video_generation_prompt || null,
    video_status: data.video_status || 'not_requested'
  },
  publish_status: {
    platform: data.platform,
    published: data.should_publish,
    post_id: data.publish_result?.id || null,
    tiktok_draft: data.tiktok_publish_status || null
  },
  confidence: brief.confidence || data.confidence || 0.8,
  timestamp: new Date().toISOString()
} }];
